package com.mediconnect.controller;
import com.mediconnect.dto.ApiDtos;import com.mediconnect.entity.*;import com.mediconnect.repository.*;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;import java.util.*;
@RestController @RequestMapping("/api/medical-records")
public class MedicalRecordController{
 private final MedicalRecordRepository repo;private final UserRepository users;private final AppointmentRepository appointments;
 public MedicalRecordController(MedicalRecordRepository r,UserRepository u,AppointmentRepository a){repo=r;users=u;appointments=a;}
 @GetMapping public List<ApiDtos.MedicalRecordView> list(@AuthenticationPrincipal User u){if(u.getRole()==Role.PLATFORM_SUPER_ADMIN)throw forbidden("Platform administrators do not have clinical record access");List<MedicalRecord>x=switch(u.getRole()){case ADMIN->repo.findByHospitalIdOrderByCreatedAtDesc(hospitalId(u));case DOCTOR->repo.findByDoctorIdOrderByCreatedAtDesc(u.getId());case PATIENT->repo.findByPatientIdOrderByCreatedAtDesc(u.getId());case PLATFORM_SUPER_ADMIN->List.of();};return x.stream().map(ApiDtos.MedicalRecordView::of).toList();}
 @PostMapping @PreAuthorize("hasRole('DOCTOR')") public ApiDtos.MedicalRecordView create(@AuthenticationPrincipal User doctor,@RequestBody Map<String,Object>b){Long pid=id(b.get("patientId")),aid=id(b.get("appointmentId"));if(pid==null||aid==null)throw bad("Patient and completed appointment are required");User p=users.findById(pid).orElseThrow(()->notFound("Patient not found"));if(p.getRole()!=Role.PATIENT||!sameHospital(doctor,p))throw bad("Patient is unavailable in this hospital");Appointment a=appointments.findById(aid).orElseThrow(()->notFound("Appointment not found"));if(!a.getDoctor().getId().equals(doctor.getId())||!a.getPatient().getId().equals(pid)||!sameHospital(doctor,a.getHospital()))throw forbidden("Appointment does not belong to this consultation");if(a.getStatus()!=AppointmentStatus.COMPLETED)throw bad("Clinical records require a completed appointment");MedicalRecord r=new MedicalRecord();r.setHospital(doctor.getHospital());r.setPatient(p);r.setDoctor(doctor);r.setAppointment(a);r.setDiagnosis(s(b,"diagnosis"));r.setNotes(s(b,"notes"));r.setVitals(s(b,"vitals"));return ApiDtos.MedicalRecordView.of(repo.save(r));}
 private static Long id(Object o){try{return o==null?null:Long.valueOf(String.valueOf(o));}catch(Exception e){return null;}}private static String s(Map<String,Object>b,String k){return b.get(k)==null?"":String.valueOf(b.get(k)).trim();}private static boolean sameHospital(User a,User b){return a.getHospital()!=null&&b.getHospital()!=null&&a.getHospital().getId().equals(b.getHospital().getId());}private static boolean sameHospital(User u,Hospital h){return u.getHospital()!=null&&h!=null&&u.getHospital().getId().equals(h.getId());}private static Long hospitalId(User u){if(u.getHospital()==null)throw forbidden("Hospital membership required");return u.getHospital().getId();}private static ResponseStatusException bad(String m){return new ResponseStatusException(HttpStatus.BAD_REQUEST,m);}private static ResponseStatusException notFound(String m){return new ResponseStatusException(HttpStatus.NOT_FOUND,m);}private static ResponseStatusException forbidden(String m){return new ResponseStatusException(HttpStatus.FORBIDDEN,m);}
}
